(function(){'use strict';
/* JAH The Enzymes Signature generator — jahdb-enzymes-signature-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-ENZYMS-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Fundamentals", "title": "What Are Enzymes", "desc": "Enzymes are biological catalysts - mostly proteins (some RNA ribozymes) that accelerate reactions 10⁶-10¹⁷-fold without being consumed. They work by lowering activation energy, stabilizing transition states - not by changing equilibria.\nSpecificity (lock-and-key → induced fit → conformational selection) makes them precise: thousands of reactions, each catalyzed, each regulated. Life's chemistry runs on enzymes - without them, reactions would take millennia.", "how": "Identify the catalyzed reaction (EC number); locate the active site. Measure rate enhancement vs uncatalyzed. Test specificity (substrate analogs). Remember: catalysts change speed, never equilibrium position.", "keys": ["Biological catalysts, mostly protein.", "10⁶-10¹⁷-fold rate acceleration.", "Lower activation energy; equilibria unchanged.", "Specificity: lock-and-key → induced fit.", "Not consumed in reactions."], "reqs": ["Reaction identified (EC number).", "Active site located.", "Rate comparison."], "stds": ["EC numbers (4-level).", "Rate enhancements as ratios."], "cites": ["Fersht A. Structure and Mechanism in Protein Science. Freeman; 1999.", "Berg JM et al. Biochemistry. 9th ed. Freeman; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Catalytic power.\"\"\"\nfor enz, fold in [(\"carbonic anhydrase\", \"1e7\"), (\"catalase\", \"1e8\"), (\"ODC\", \"1e17\")]:\n    print(f\"  {enz:19s}: {fold}x faster\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "Activation Energy and Catalysis", "desc": "Reactions need activation energy (Ea) - the hill to the transition state. Enzymes carve a lower pass: binding substrate, stabilizing the transition state (Pauling's insight), releasing product. Rate depends exponentially on Ea (Arrhenius) - small Ea cuts, huge speedups.\nStrategies: proximity/orientation, acid-base catalysis, covalent catalysis, metal ions, electrostatic stabilization, desolvation. Catalytic perfection (diffusion limit ~10⁸-10⁹ M⁻¹s⁻¹) needs no further improvement.", "how": "Draw energy diagrams (catalyzed vs uncatalyzed - same ΔG, lower Ea). Identify catalytic strategy from structure/mechanism. Compute rate enhancement from Ea difference (Arrhenius). Test by mutating catalytic residues.", "keys": ["Lower Ea, same ΔG.", "Transition-state stabilization (Pauling).", "Arrhenius: exponential in Ea.", "Strategies: proximity, acid-base, covalent, metals.", "Diffusion limit: catalytic perfection."], "reqs": ["Energy diagram.", "Catalytic residues.", "Rate comparison."], "stds": ["Ea in kJ/mol.", "kcat/KM in M⁻¹s⁻¹."], "cites": ["Pauling L. Chem Eng News 1946;24:1375-1377.", "Fersht A. Structure and Mechanism in Protein Science. Freeman; 1999."], "demo": "#!/usr/bin/env python3\n\"\"\"Arrhenius: Ea cut of 20 kJ/mol at 25 C.\"\"\"\nimport math\nR = 8.314e-3  # kJ/mol/K\nenhance = math.exp(20/(R*298))\nprint(f\"  rate enhancement: {enhance:.0e}x\")\n"}, {"tier": "Foundations", "g": "Structure", "title": "Enzyme Structure: The Active Site", "desc": "The active site: a 3D pocket (a few residues) binding substrate and doing chemistry - the rest of the protein is scaffold, positioning, and dynamics. Binding (Km) and catalysis (kcat) are separable functions of the site.\nInduced fit (Koshland): substrate molds the site; conformational selection: pre-existing ensembles shift. Dynamics matter - enzymes breathe, and motions couple to catalysis (DHFR's loops). Structure without dynamics is a statue.", "how": "Locate the active site (structure, mutagenesis); map binding vs catalytic residues. Distinguish induced fit from conformational selection (kinetics, NMR). Consider dynamics (MD simulations, H/D exchange) in mechanism.", "keys": ["Active site: binding + chemistry.", "Scaffold positions catalytic residues.", "Induced fit (Koshland).", "Dynamics couple to catalysis.", "Binding and catalysis separable."], "reqs": ["Structure/mutagenesis data.", "Binding vs catalytic residues.", "Dynamics assessment."], "stds": ["Residues numbered.", "PDB IDs cited."], "cites": ["Koshland DE. Proc Natl Acad Sci 1958;44:98-104.", "Fersht A. Structure and Mechanism in Protein Science. Freeman; 1999."], "demo": "#!/usr/bin/env python3\n\"\"\"Active-site residue roles.\"\"\"\nroles = {\"binding\": \"positions substrate\", \"catalytic\": \"does chemistry\", \"scaffold\": \"holds geometry\"}\nfor r, fn in roles.items():\n    print(f\"  {r:10s}: {fn}\")\n"}, {"tier": "Foundations", "g": "Nomenclature", "title": "Enzyme Classification (EC Numbers)", "desc": "EC numbers classify by reaction: 1 oxidoreductases, 2 transferases, 3 hydrolases, 4 lyases, 5 isomerases, 6 ligases, 7 translocases - four levels (EC 1.1.1.1 = alcohol dehydrogenase). IUBMB maintains the system.\nNames: systematic (reaction-based) vs trivial (historical: trypsin, pepsin). Classification by chemistry, not structure - convergent enzymes share EC numbers. Databases: BRENDA, ExplorEnz, UniProt.", "how": "Assign EC by reaction chemistry (not structure); look up in BRENDA/ExplorEnz. Use systematic names in formal writing, trivial where standard. Cross-reference UniProt for sequences. Note: one EC, many unrelated structures (convergence).", "keys": ["7 classes by reaction type.", "4-level EC numbers.", "Chemistry, not structure.", "BRENDA/ExplorEnz databases.", "Systematic vs trivial names."], "reqs": ["Reaction chemistry.", "EC assignment.", "Database cross-reference."], "stds": ["EC numbers 4-level.", "IUBMB nomenclature."], "cites": ["IUBMB Enzyme Nomenclature.", "Schomburg I et al. Nucleic Acids Res (BRENDA)."], "demo": "#!/usr/bin/env python3\n\"\"\"EC classes.\"\"\"\nfor n, name in [(1, \"oxidoreductases\"), (2, \"transferases\"), (3, \"hydrolases\"), (4, \"lyases\"), (5, \"isomerases\"), (6, \"ligases\"), (7, \"translocases\")]:\n    print(f\"  EC {n}: {name}\")\n"}, {"tier": "Foundations", "g": "Kinetics", "title": "Michaelis-Menten Kinetics", "desc": "The kinetic law: v = Vmax[S]/(Km + [S]) - hyperbolic saturation. Km (substrate at half-Vmax) measures affinity (lower = tighter); Vmax = kcat[E]ₜ; kcat/KM is catalytic efficiency. Michaelis-Menten (1913), Briggs-Haldane steady-state derivation.\nLinearizations (Lineweaver-Burk: 1/v vs 1/[S]) estimate parameters - fit nonlinearly in practice. Assumptions: steady state, [S] >> [E], initial rates, no inhibition/product effects.", "how": "Measure initial rates across [S] (bracketing Km); fit v = Vmax[S]/(Km+[S]) nonlinearly. Report Km, kcat, kcat/KM with errors. Check assumptions (linearity in [E], initial-rate regime). Use Lineweaver-Burk only for display/diagnosis.", "keys": ["v = Vmax[S]/(Km + [S]).", "Km: affinity; kcat: turnover; kcat/KM: efficiency.", "1913; Briggs-Haldane steady state.", "Hyperbolic saturation.", "Fit nonlinearly; linearize for display."], "reqs": ["Initial-rate data.", "[S] bracketing Km.", "Steady-state validation."], "stds": ["Km in mM/µM; kcat in s⁻¹.", "Errors reported."], "cites": ["Michaelis L, Menten ML. Biochem Z 1913;49:333-369.", "Fersht A. Structure and Mechanism in Protein Science. Freeman; 1999."], "demo": "#!/usr/bin/env python3\n\"\"\"Michaelis-Menten curve.\"\"\"\ndef v(S, Vmax=100, Km=2):\n    return Vmax*S/(Km+S)\nfor S in (0.5, 2, 10):\n    print(f\"  [S]={S} mM: v = {v(S):.0f} (Vmax=100, Km=2)\")\n"}, {"tier": "Foundations", "g": "Specificity", "title": "Enzyme Specificity", "desc": "Specificity: which substrates react - absolute (urease: urea only), group (hexokinase: hexoses), linkage (proteases: peptide bonds), stereochemical (L-amino acids). Measured as kcat/KM ratios between substrates.\nBasis: binding energy pays for selectivity (transition-state complementarity). Promiscuity (side reactions) is evolution's raw material - new functions from old scaffolds. Specificity constants up to 10⁸-fold.", "how": "Measure kcat/KM for substrate panels; compute specificity ratios. Map binding determinants (structures with analogs); mutate to alter specificity. Exploit promiscuity for engineering (directed evolution starts from side activities).", "keys": ["Absolute to stereochemical: the range.", "kcat/KM ratios quantify.", "Transition-state complementarity.", "Promiscuity enables evolution.", "Up to 10⁸-fold discrimination."], "reqs": ["Substrate panel data.", "kcat/KM per substrate.", "Structural basis."], "stds": ["Specificity as ratios.", "Stereochemistry stated."], "cites": ["Fersht A. Structure and Mechanism in Protein Science. Freeman; 1999.", "Berg JM et al. Biochemistry. 9th ed. Freeman; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Specificity ratio.\"\"\"\ndef spec(kcat_KM_good, kcat_KM_bad):\n    return kcat_KM_good/kcat_KM_bad\nprint(f\"  1e7 vs 1e2 M-1s-1: {spec(1e7, 1e2):.0e}-fold specific\")\n"}, {"tier": "Foundations", "g": "Cofactors", "title": "Cofactors and Coenzymes", "desc": "Cofactors enable chemistry proteins can't do alone: metal ions (Zn²⁺ Lewis acid, Fe heme redox, Mg²⁺ phosphate handling) and coenzymes (NAD⁺/NADH redox, FAD, CoA acyl carrier, PLP amino-acid chemistry, TPP decarboxylation - many are B vitamins).\nProsthetic groups bind tightly (heme); cosubstrates loosely (NAD⁺ cycles). Apoenzyme + cofactor = holoenzyme. Vitamin deficiencies are cofactor deficiencies (beriberi: B1/TPP, pellagra: B3/NAD⁺).", "how": "Identify cofactor (spectroscopy, activity ± additions); reconstitute apoenzyme to test. Track cosubstrate stoichiometry (NADH at 340 nm). Supplement deficiencies (vitamins). Design assays around cofactor signals.", "keys": ["Metals + coenzymes extend chemistry.", "Many coenzymes are B vitamins.", "Prosthetic (tight) vs cosubstrate (loose).", "Apo + cofactor = holoenzyme.", "Vitamin deficiency = cofactor deficiency."], "reqs": ["Cofactor identity.", "Binding mode.", "Reconstitution test."], "stds": ["Cofactors named (NAD⁺, PLP...).", "Stoichiometry stated."], "cites": ["Berg JM et al. Biochemistry. 9th ed. Freeman; 2019.", "Fersht A. Structure and Mechanism in Protein Science. Freeman; 1999."], "demo": "#!/usr/bin/env python3\n\"\"\"NADH assay signal.\"\"\"\nprint(\"  NADH absorbs at 340 nm (NAD+ does not)\")\nprint(\"  ΔA340 tracks redox reactions directly\")\n"}, {"tier": "Foundations", "g": "Regulation", "title": "Enzyme Regulation Overview", "desc": "Activity is controlled: reversible (allosteric effectors, covalent modification - phosphorylation, pH/temperature), irreversible (zymogen activation by proteolysis, degradation), and by amount (synthesis/degradation - slow).\nAllostery (Monod-Wyman-Changeux): effectors bind away from the active site, shifting conformations - feedback inhibition's mechanism (end product inhibits first committed step). Regulation makes metabolism responsive, not just fast.", "how": "Identify regulatory inputs (effectors, modifications, zymogen cleavage); map to physiological need (feedback loops). Test allostery (sigmoidal kinetics, effector titrations). Distinguish activity regulation from amount regulation.", "keys": ["Reversible: allostery, modification.", "Irreversible: zymogen activation.", "Amount: synthesis/degradation.", "Feedback inhibition: end product blocks start.", "MWC model of allostery."], "reqs": ["Regulatory input identified.", "Physiological rationale.", "Kinetics ± effector."], "stds": ["Effector concentrations.", "Modification sites."], "cites": ["Monod J et al. J Mol Biol 1965;12:88-118.", "Berg JM et al. Biochemistry. 9th ed. Freeman; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Feedback inhibition logic.\"\"\"\nprint(\"  A →(E1)→ B →(E2)→ C; C inhibits E1\")\nprint(\"  result: pathway self-limits; no waste\")\n"}, {"tier": "Foundations", "g": "Examples", "title": "Famous Enzymes: Lysozyme, Chymotrypsin, Carbonic Anhydrase", "desc": "Lysozyme: first enzyme structure (Phillips 1965) - glycosidic-bond cleavage via oxocarbenium transition state (mechanism revised over decades - science refining). Chymotrypsin: serine-protease catalytic triad (Ser-His-Asp), covalent acyl-enzyme intermediate.\nCarbonic anhydrase: CO₂ hydration at 10⁶/s (Zn²⁺-bound hydroxide attacks) - near diffusion-controlled; drug target (acetazolamide for glaucoma/altitude). Three enzymes, three mechanistic paradigms.", "how": "Study as case histories: structure → mechanism → revision. Identify catalytic motifs (triads, metal centers); test by mutagenesis. Target therapeutically (transition-state analogs). Teach mechanisms comparatively.", "keys": ["Lysozyme: first structure (1965).", "Chymotrypsin: catalytic triad.", "Carbonic anhydrase: 10⁶/s, Zn²⁺.", "Mechanisms get revised (lysozyme).", "Transition-state analog drugs."], "reqs": ["Structure (PDB).", "Catalytic residues.", "Kinetic parameters."], "stds": ["Mechanisms with evidence.", "kcat/KM values."], "cites": ["Phillips DC. Sci Am 1966;214:78-90.", "Fersht A. Structure and Mechanism in Protein Science. Freeman; 1999."], "demo": "#!/usr/bin/env python3\n\"\"\"Catalytic triad charge relay.\"\"\"\nprint(\"  Asp → His → Ser: proton shuttle activates serine\")\nprint(\"  result: covalent acyl-enzyme intermediate\")\n"}, {"tier": "Foundations", "g": "Measurement", "title": "Measuring Enzyme Activity", "desc": "Assays track product/substrate/cosubstrate: spectrophotometric (NADH 340 nm, pNPP 405 nm), fluorometric (sensitive), radiometric (classic), coupled assays (link to a detectable reaction). Units: katal (mol/s) or IU (µmol/min); specific activity (per mg).\nDesign: initial rates, substrate saturation (or fixed [S]), controls (no enzyme, no substrate), blanks. Purification tracked by specific activity (fold purification, yield) - the purification table.", "how": "Choose detection (sensitivity vs convenience); validate linearity (time, enzyme). Use initial rates; include controls. Track purification (specific activity, fold, yield). Report conditions (pH, T, [S]) - activities are conditional.", "keys": ["Track product/substrate/cosubstrate.", "Spectrophotometric: convenient; fluoro: sensitive.", "Katal (SI) / IU (µmol/min).", "Specific activity tracks purification.", "Initial rates; conditions reported."], "reqs": ["Detection method.", "Linearity validation.", "Controls."], "stds": ["Units (katal or IU).", "Conditions (pH, T, [S])."], "cites": ["Berg JM et al. Biochemistry. 9th ed. Freeman; 2019.", "Scopes RK. Protein Purification. 3rd ed. Springer; 1994."], "demo": "#!/usr/bin/env python3\n\"\"\"Specific activity through purification.\"\"\"\nsteps = [(\"crude\", 100, 2), (\"salt cut\", 80, 10), (\"column\", 60, 50)]\nfor name, mg, sa in steps:\n    print(f\"  {name:9s}: {sa} U/mg (total {mg*sa} U)\")\n"}, {"tier": "Foundations", "g": "History", "title": "History: From Ferments to Structures", "desc": "Ferments (vitalism) → Buchner's cell-free fermentation (1897, Nobel 1907: no vital force) → Sumner crystallizes urease (1926: enzymes are proteins, Nobel 1946) → Michaelis-Menten (1913) → Pauling's transition-state theory → first structures (lysozyme 1965) → ribozymes (1989) → directed evolution (2018).\nEach era's tool (crystallography, kinetics, genetics) remade the field. The arc: mysterious ferments → understood molecular machines → engineered catalysts.", "how": "Teach as experiments defeating vitalism (Buchner) and revealing proteins (Sumner). Trace theory (Pauling) → structure (Phillips) → engineering (Arnold). Note the long gaps - tools pace discovery.", "keys": ["Buchner 1897: no vital force.", "Sumner 1926: enzymes are proteins.", "Pauling: transition-state theory.", "Lysozyme 1965: first structure.", "Ribozymes 1989; directed evolution 2018."], "reqs": ["Primary sources.", "Experimental logic.", "Timeline accuracy."], "stds": ["Nobel citations.", "Dates with discoveries."], "cites": ["Buchner E. (Nobel 1907).", "Sumner JB. (Nobel 1946)."], "demo": "#!/usr/bin/env python3\n\"\"\"Enzymology timeline.\"\"\"\nfor y, e in [(1897, \"cell-free fermentation\"), (1926, \"urease crystallized\"), (1965, \"lysozyme structure\"), (1989, \"ribozymes\"), (2018, \"directed evolution\")]:\n    print(f\"  {y}: {e}\")\n"}, {"tier": "Compounded", "g": "Mechanism", "title": "Catalytic Mechanisms in Detail", "desc": "How enzymes do chemistry: acid-base (His proton shuttles), covalent (Ser nucleophile → acyl-enzyme; PLP Schiff bases), metal-ion (Zn²⁺ polarizes, Fe redox), electrostatic (oxyanion holes stabilize charges), proximity/orientation (effective molarity), desolvation (low-dielectric active sites strengthen electrostatics).\nMost enzymes combine several - chymotrypsin uses covalent + acid-base + oxyanion hole. Mechanisms are tested by kinetics (pH-rate profiles reveal pKas), mutagenesis, isotope effects, and structures of transition-state analogs.", "how": "Propose mechanism from structure (catalytic residues, metals); test by pH-rate profiles (ionizable groups), mutagenesis (essential residues), kinetic isotope effects (rate-determining step). Trap intermediates (cryo, analogs).", "keys": ["Acid-base, covalent, metal, electrostatic.", "Proximity + desolvation.", "Oxyanion holes stabilize charges.", "Mechanisms combine strategies.", "pH-rate profiles reveal pKas."], "reqs": ["Catalytic residues/metals.", "pH-rate data.", "Intermediate evidence."], "stds": ["Mechanisms as arrow-pushing.", "pKas stated."], "cites": ["Fersht A. Structure and Mechanism in Protein Science. Freeman; 1999.", "Berg JM et al. Biochemistry. 9th ed. Freeman; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Catalytic strategies checklist.\"\"\"\nfor s in [\"acid-base\", \"covalent\", \"metal ion\", \"electrostatic\", \"proximity\", \"desolvation\"]:\n    print(f\"  [ ] {s}\")\n"}, {"tier": "Compounded", "g": "Mechanism", "title": "Transition-State Theory (Pauling)", "desc": "Pauling (1946): enzymes bind the transition state tighter than substrate - the binding energy pays for the barrier. Implication: transition-state analogs are the ultimate inhibitors (designed drugs: HIV protease inhibitors, neuraminidase's oseltamivir).\nEvidence: catalytic antibodies (raised against analogs, catalyze), tight analog binding (10⁶× substrate affinity), computational QM/MM barriers matching rates. The most powerful idea in enzymology - chemistry explained by binding.", "how": "Design analogs mimicking the transition state (geometry, charge); measure binding (should exceed substrate hugely). Raise catalytic antibodies as tests. Compute barriers (QM/MM) vs experimental rates. Drug the transition state.", "keys": ["Bind TS tighter than substrate.", "Pauling 1946.", "Analogs: ultimate inhibitors.", "Catalytic antibodies prove it.", "HIV/flu drugs are TS analogs."], "reqs": ["TS structure hypothesis.", "Analog binding data.", "Rate correlation."], "stds": ["Binding as Kd/Ki.", "Analog structures."], "cites": ["Pauling L. Chem Eng News 1946;24:1375-1377.", "Schramm VL. Annu Rev Biochem 1998;67:693-720."], "demo": "#!/usr/bin/env python3\n\"\"\"TS analog binding advantage.\"\"\"\nprint(\"  substrate Kd: 1e-3 M; TS analog Ki: 1e-9 M\")\nprint(\"  -> 1e6x tighter: the TS stabilization energy\")\n"}, {"tier": "Compounded", "g": "Kinetics", "title": "Enzyme Inhibition", "desc": "Inhibitors: competitive (bind active site; Vmax same, Km up - overcome by [S]), uncompetitive (bind ES; both down), noncompetitive/mixed (bind elsewhere; Vmax down), irreversible (covalent - aspirin on COX, penicillin on transpeptidase).\nDiagnose by Lineweaver-Burk patterns (intersect where?). Ki quantifies potency; IC₅₀ is conditional. Drugs are inhibitors: statins (HMG-CoA reductase), ACE inhibitors, methotrexate (DHFR) - most medicines jam enzymes.", "how": "Vary [S] ± inhibitor; fit to inhibition models; diagnose type by double-reciprocal pattern. Determine Ki (not just IC₅₀). Test reversibility (dilution/dialysis). Design drugs as TS/substrate analogs with selectivity.", "keys": ["Competitive: Km up, Vmax same.", "Noncompetitive: Vmax down.", "Uncompetitive: both down.", "Irreversible: covalent (aspirin, penicillin).", "Ki quantifies; IC50 is conditional."], "reqs": ["Inhibition type diagnosis.", "Ki determination.", "Reversibility test."], "stds": ["Lineweaver-Burk patterns.", "Ki in nM/µM."], "cites": ["Fersht A. Structure and Mechanism in Protein Science. Freeman; 1999.", "Berg JM et al. Biochemistry. 9th ed. Freeman; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Inhibition diagnosis.\"\"\"\npatterns = {\"competitive\": \"lines meet on y-axis\", \"noncompetitive\": \"lines meet on x-axis\", \"uncompetitive\": \"parallel lines\"}\nfor t, p in patterns.items():\n    print(f\"  {t:15s}: {p}\")\n"}, {"tier": "Compounded", "g": "Kinetics", "title": "Allosteric Regulation", "desc": "Allostery: effectors bind away from the active site, shifting T↔R conformations (MWC concerted model; KNF sequential as alternative). Sigmoidal kinetics (Hill coefficient > 1) signal cooperativity - hemoglobin's O₂ binding is the paradigm.\nFeedback inhibition (end product → first committed step), feedforward activation, covalent modification cascades (phosphorylation amplifies). ATCase (pyrimidine synthesis) is the textbook MWC enzyme - CTP inhibits, ATP activates.", "how": "Test for sigmoidicity (Hill plot); titrate effectors (activators/inhibitors). Fit MWC (L, c parameters) vs KNF. Map effector sites (structures ± ligands). Trace physiological logic (why this effector?).", "keys": ["Effectors bind away from active site.", "MWC: T↔R concerted shift.", "Sigmoidal = cooperative.", "ATCase: the textbook example.", "Feedback/feedforward logic."], "reqs": ["Effector identities.", "Conformational states.", "Physiological rationale."], "stds": ["Hill coefficients.", "MWC parameters (L, c)."], "cites": ["Monod J et al. J Mol Biol 1965;12:88-118.", "Berg JM et al. Biochemistry. 9th ed. Freeman; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Hill equation: cooperativity.\"\"\"\ndef v_hill(S, n=2.8, K=1.0):\n    return S**n/(K**n+S**n)\nfor S in (0.5, 1.0, 2.0):\n    print(f\"  [S]={S}: v/Vmax = {v_hill(S):.2f} (n=2.8)\")\n"}, {"tier": "Compounded", "g": "Kinetics", "title": "pH and Temperature Effects", "desc": "pH: ionizable catalytic residues need correct protonation - bell-shaped profiles reveal pKas (chymotrypsin's His 57). Extremes denature. Optima match environment (pepsin pH 2, trypsin pH 8).\nTemperature: rates rise (Q₁₀ ~2) then crash at denaturation - the asymmetric curve. Thermophilic enzymes (Taq polymerase) trade flexibility for stability; psychrophilic trade stability for low-T activity. Stability vs activity is the eternal trade-off.", "how": "Profile pH-rate (identify pKas from limbs); profile temperature (find optimum, denaturation onset). Fit to ionization models. Engineer stability (disulfides, consensus) vs activity per application. Report both in characterization.", "keys": ["Bell-shaped pH profiles reveal pKas.", "Optima match environments.", "Q10 ~2 then denaturation crash.", "Thermophiles: stable; psychrophiles: active cold.", "Stability-activity trade-off."], "reqs": ["pH-rate profile.", "Temperature profile.", "Denaturation data."], "stds": ["pH optima; pKas.", "Tm in °C."], "cites": ["Fersht A. Structure and Mechanism in Protein Science. Freeman; 1999.", "Berg JM et al. Biochemistry. 9th ed. Freeman; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"pH optimum logic.\"\"\"\nfor enz, opt in [(\"pepsin\", 2), (\"chymotrypsin\", 8), (\"lysozyme\", 5)]:\n    print(f\"  {enz:14s}: pH {opt} (matches environment)\")\n"}, {"tier": "Compounded", "g": "Families", "title": "Proteases", "desc": "Peptide-bond cutters by mechanism: serine (chymotrypsin triad), cysteine (papain), aspartyl (HIV protease - drug target), metallo (carboxypeptidase Zn²⁺), threonine (proteasome). Specificity pockets (S1...) read substrate side chains.\nRegulated by zymogens (trypsinogen → trypsin; blood-clotting cascade) and inhibitors (serpins - α1-antitrypsin deficiency causes emphysema). Drugs: HIV protease inhibitors, ACE inhibitors, DPP-4 inhibitors (diabetes).", "how": "Classify by catalytic mechanism (inhibitor profiling: PMSF/serine, E-64/cysteine, pepstatin/aspartyl, EDTA/metallo); map specificity pockets. Control activation (zymogens) and inhibition (serpins). Drug active sites selectively.", "keys": ["5 mechanistic classes.", "Catalytic triads/pockets.", "Zymogens + serpins regulate.", "HIV/ACE/DPP-4: drug targets.", "Inhibitor profiling classifies."], "reqs": ["Mechanistic class.", "Specificity map.", "Regulation (zymogen/inhibitor)."], "stds": ["MEROPS classification.", "Cleavage sites (P1-P1′)."], "cites": ["Rawlings ND et al. Nucleic Acids Res (MEROPS).", "Berg JM et al. Biochemistry. 9th ed. Freeman; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Protease class by inhibitor.\"\"\"\nprof = {\"PMSF\": \"serine\", \"E-64\": \"cysteine\", \"pepstatin\": \"aspartyl\", \"EDTA\": \"metallo\"}\nfor inh, cls in prof.items():\n    print(f\"  inhibited by {inh:9s} -> {cls} protease\")\n"}, {"tier": "Compounded", "g": "Families", "title": "Kinases and Phosphatases", "desc": "Kinases transfer phosphate from ATP (protein kinases: Ser/Thr, Tyr - signaling; metabolic kinases: hexokinase). The human kinome: 538 kinases - the druggable genome's crown (imatinib/Gleevec for BCR-Abl CML: the targeted-therapy proof).\nPhosphatases reverse (PP1/PP2A Ser/Thr; PTPs Tyr) - signaling is the balance. Kinase cascades (MAPK: Raf→MEK→ERK) amplify and integrate. Mutations drive cancer (BRAF V600E); inhibitors are precision medicine.", "how": "Assay phosphotransfer (³²P, ADP-Glo, phospho-antibodies); profile selectivity (kinome screens). Inhibit selectively (type I/II/III); test resistance mutations. Map cascades (phosphoproteomics).", "keys": ["Kinases add phosphate; phosphatases remove.", "Human kinome: 538.", "Imatinib: targeted therapy proof.", "MAPK cascade amplifies.", "BRAF V600E: cancer driver."], "reqs": ["Kinase/substrate identity.", "Phosphosite.", "Selectivity profile."], "stds": ["Sites as residue numbers.", "Inhibitor IC50s + kinome profile."], "cites": ["Manning G et al. Science 2002;298:1912-1934.", "Druker BJ et al. (Imatinib, NEJM 2001)."], "demo": "#!/usr/bin/env python3\n\"\"\"Kinase cascade amplification.\"\"\"\nsteps = [\"Raf\", \"MEK\", \"ERK\"]\namp = 100\nfor i, s in enumerate(steps, 1):\n    print(f\"  tier {i} ({s}): signal amplifies ~100x\")\n"}, {"tier": "Compounded", "g": "Families", "title": "Polymerases (as Enzymes)", "desc": "Template-directed polymerases: DNA pols (replication - proofreading 3′→5′ exonuclease; fidelity 10⁻⁷-10⁻¹⁰ with repair), RNA pols (transcription), reverse transcriptases (retroviruses - drug targets), Taq (PCR's heat-stable workhorse).\nMechanism: two-metal-ion catalysis (Steitz) - universal across polymerases. Processivity (clamps, thioredoxin) vs distributivity. Fidelity-speed trade-offs; error-prone pols (Y-family) bypass lesions (XPV patients lack pol η).", "how": "Assay synthesis (incorporation, processivity); measure fidelity (reporter assays). Inhibit selectively (nucleoside analogs: AZT, acyclovir - chain terminators). Engineer (Taq for PCR, high-fidelity for cloning).", "keys": ["Template-directed synthesis.", "Two-metal-ion mechanism (universal).", "Proofreading: 3′→5′ exonuclease.", "Taq: PCR's thermostable enzyme.", "Nucleoside analogs: chain terminators."], "reqs": ["Polymerase family.", "Template/primer.", "Fidelity measurement."], "stds": ["Error rates per base.", "Processivity (nt/binding)."], "cites": ["Steitz TA. Nature 1998;391:231-232.", "Berg JM et al. Biochemistry. 9th ed. Freeman; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Fidelity ladder.\"\"\"\nfor pol, err in [(\"Taq\", \"1e-4\"), (\"Pol delta + MMR\", \"1e-10\"), (\"HIV RT\", \"1e-4\")]:\n    print(f\"  {pol:15s}: {err} errors/base\")\n"}, {"tier": "Compounded", "g": "Regulation", "title": "Zymogens and Proteolytic Activation", "desc": "Zymogens: inactive precursors activated by proteolysis - irreversible, one-way switches. Digestive (trypsinogen → trypsin by enteropeptidase; cascade amplifies), blood clotting (factors XII→IIa cascade - each step amplifies ~10⁴×), apoptosis (procaspases → caspases).\nWhy irreversible: commitment (digestion, clotting, death shouldn't reverse). Controlled by localization (pancreas vs intestine), inhibitors (antithrombin), and cofactors. Dysregulation: pancreatitis (early activation), hemophilia (missing factor).", "how": "Identify activation cleavage (N-terminal sequencing); trigger in vitro (enteropeptidase for trypsinogen). Measure cascade amplification; test inhibitors (antithrombin, serpins). Diagnose deficiencies (clotting factor assays).", "keys": ["Inactive precursors; proteolysis activates.", "Irreversible: commitment switches.", "Cascades amplify (clotting).", "Caspases: death by zymogen.", "Pancreatitis: premature activation."], "reqs": ["Zymogen/activator pair.", "Cleavage site.", "Inhibitor control."], "stds": ["Cleavage sites stated.", "Amplification factors."], "cites": ["Neurath H, Walsh KA. Proc Natl Acad Sci 1976;73:3825-3832.", "Berg JM et al. Biochemistry. 9th ed. Freeman; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Clotting cascade amplification (toy).\"\"\"\namp = 1\nfor step in [\"XIIa\", \"XIa\", \"IXa\", \"Xa\", \"thrombin\"]:\n    amp *= 30\n    print(f\"  {step:9s}: x{amp:.0e} cumulative\")\n"}, {"tier": "Compounded", "g": "Cofactors", "title": "Metalloenzymes", "desc": "Metals do what amino acids can't: Zn²⁺ (Lewis acid - carbonic anhydrase, carboxypeptidase), Fe (heme redox - cytochromes, P450; Fe-S clusters - electron transfer), Cu (oxidases), Mn (photosystem II water-splitting), Mg²⁺ (phosphate - kinases, polymerases), Mo/W (oxo transfer), Ni (urease, hydrogenase).\nCoordination geometry tunes reactivity; metal choice is ancient (Fe in anoxic world, Cu/Zn after oxygenation). Chelation therapy (EDTA, desferrioxamine) and metal-based drugs (cisplatin) exploit metal chemistry.", "how": "Identify metal (ICP-MS, spectroscopy - EPR for paramagnetic, XAS for geometry); remove (chelation) and reconstitute to test necessity. Assign role (Lewis acid, redox, structural). Mind metal homeostasis (toxicity of free metals).", "keys": ["Zn²⁺: Lewis acid catalysis.", "Fe: redox (heme, Fe-S).", "Mg²⁺: phosphate handling.", "Geometry tunes reactivity.", "Metal choice is ancient."], "reqs": ["Metal identity.", "Coordination geometry.", "Reconstitution test."], "stds": ["Metals with oxidation states.", "Ligands specified."], "cites": ["Berg JM et al. Biochemistry. 9th ed. Freeman; 2019.", "Holm RH et al. Chem Rev 1996;96:2239-2314."], "demo": "#!/usr/bin/env python3\n\"\"\"Metal-role map.\"\"\"\nfor metal, role in [(\"Zn2+\", \"Lewis acid\"), (\"Fe2+/3+\", \"redox\"), (\"Mg2+\", \"phosphate\"), (\"Mn\", \"water splitting\")]:\n    print(f\"  {metal:8s}: {role}\")\n"}, {"tier": "Compounded", "g": "Ribozymes", "title": "Ribozymes: Catalytic RNA", "desc": "RNA can catalyze: self-splicing introns (Cech, Tetrahymena 1982), RNase P (Altman - tRNA processing), ribosome's peptidyl transferase (the ribosome is a ribozyme), hammerhead ribozymes (self-cleaving). Nobel 1989 to Cech/Altman.\nImplication: the RNA world (genetics + catalysis in one molecule) - ribozymes are living fossils. Engineered ribozymes (aptazymes) sense and act; deoxyribozymes extend catalysis to DNA.", "how": "Test catalysis in protein-free preparations (the defining experiment); map catalytic cores (mutagenesis, structures). Measure rates vs protein enzymes (slower, but real). Engineer (in vitro selection - SELEX for new activities).", "keys": ["RNA catalyzes (Cech/Altman 1982).", "Ribosome: a ribozyme.", "RNase P processes tRNA.", "Nobel 1989.", "RNA-world living fossils."], "reqs": ["Protein-free demonstration.", "Catalytic core mapping.", "Rate measurement."], "stds": ["Rates in min⁻¹.", "Metal dependence stated."], "cites": ["Cech TR et al. Cell 1982;31:147-157.", "Guerrier-Takada C et al. Cell 1983;35:849-857."], "demo": "#!/usr/bin/env python3\n\"\"\"Ribozyme examples.\"\"\"\nfor rz, fn in [(\"group I intron\", \"self-splicing\"), (\"RNase P\", \"tRNA processing\"), (\"ribosome\", \"peptide bonds\"), (\"hammerhead\", \"self-cleavage\")]:\n    print(f\"  {rz:15s}: {fn}\")\n"}, {"tier": "Compounded", "g": "Applications", "title": "Industrial Enzymes", "desc": "Enzymes at scale: detergents (proteases/lipases - 1960s onward), food (amylases brewing, rennet cheese, pectinases juice), textiles (cellulases stone-washing), biofuels (cellulases → sugars → ethanol), paper (xylanases bleach-boosting).\nRequirements: stability (heat, pH, solvents), cost (fermentation production), immobilization (reuse - packed beds). Protein engineering (directed evolution, Arnold Nobel 2018) tailors enzymes to process conditions - evolution in the service of industry.", "how": "Match enzyme to process (conditions first); engineer stability (directed evolution, consensus design); immobilize for reuse (carriers, crosslinking); optimize fermentation production. Cost per kg product is the metric.", "keys": ["Detergents, food, textiles, biofuels.", "Stability under process conditions.", "Immobilization enables reuse.", "Directed evolution tailors (2018).", "Cost per kg is the metric."], "reqs": ["Process conditions.", "Stability data.", "Cost analysis."], "stds": ["Activities under process conditions.", "Half-lives at operating T."], "cites": ["Kirk O et al. Curr Opin Biotechnol 2002;13:345-351.", "Arnold FH. (Nobel 2018, directed evolution)."], "demo": "#!/usr/bin/env python3\n\"\"\"Immobilization reuse benefit.\"\"\"\nuses, cost_per_use = 100, 1.0\nprint(f\"  free enzyme: 1 use = $1.00/use\")\nprint(f\"  immobilized: {uses} uses = ${cost_per_use/uses:.2f}/use\")\n"}, {"tier": "Advanced", "g": "Engineering", "title": "Directed Evolution", "desc": "Arnold's method (Nobel 2018): mutate (error-prone PCR, shuffling), screen/select, repeat - evolution in weeks. Created enzymes for non-natural reactions (carbon-silicon bonds), industrial conditions (heat, solvents), and therapeutics.\nCycle: diversity → selection pressure → winners → repeat. Screens (colorimetric) or selections (growth-coupled) find rare improvements; recombination (DNA shuffling) combines them. The fitness landscape is navigated, not designed - engineering without full understanding.", "how": "Generate diversity (epPCR, site-saturation); screen/select under target conditions (throughput is king - FACS, microfluidics); recombine winners; iterate. Validate improvements (kinetics); characterize trade-offs. Start from promiscuous activities.", "keys": ["Mutate → screen → repeat.", "Arnold Nobel 2018.", "Non-natural reactions created.", "Throughput is king.", "Recombination combines wins."], "reqs": ["Diversity method.", "Screen/selection.", "Iteration count."], "stds": ["Library sizes stated.", "Improvements as fold-change."], "cites": ["Arnold FH. (Nobel 2018).", "Bloom JD, Arnold FH. Proc Natl Acad Sci 2009;106:9995-10000."], "demo": "#!/usr/bin/env python3\n\"\"\"Directed evolution cycle.\"\"\"\nfor rnd in range(1, 4):\n    print(f\"  round {rnd}: diversify -> screen 1e4 -> keep top 10\")\n"}, {"tier": "Advanced", "g": "Engineering", "title": "Rational Enzyme Design", "desc": "Design from principles: active-site remodeling (Rosetta), de novo enzymes (Kemp eliminases, Diels-Alderases - designed then evolved), computational enzyme design (theozymes: idealized transition-state arrangements).\nReality check: designed enzymes are weak (10³-10⁵ below natural) - directed evolution finishes them. The combo (design → evolve) works: design places chemistry, evolution optimizes. AI (RFdiffusion, ProteinMPNN) now designs binders and catalysts - the field's new engine.", "how": "Model the transition state (QM); place catalytic groups (theozyme); scaffold (Rosetta); build and test (weak activity expected); evolve to improve. Validate structures (crystallography). Combine with directed evolution always.", "keys": ["Theozymes: idealized TS arrangements.", "De novo: Kemp, Diels-Alderases.", "Designed enzymes start weak.", "Design → evolve: the winning combo.", "AI design (RFdiffusion) emerging."], "reqs": ["TS model.", "Scaffold choice.", "Evolution follow-up."], "stds": ["kcat/KM vs natural.", "Structures validated."], "cites": ["Rothlisberger D et al. Nature 2008;453:190-195.", "Jiang L et al. Science 2008;319:1387-1391."], "demo": "#!/usr/bin/env python3\n\"\"\"Design-then-evolve gains.\"\"\"\nfor stage, eff in [(\"designed\", 1e2), (\"evolved\", 1e6), (\"natural\", 1e8)]:\n    print(f\"  {stage:9s}: kcat/KM ~ {eff:.0e} M-1s-1\")\n"}, {"tier": "Advanced", "g": "Medicine", "title": "Enzymes as Drugs and Drug Targets", "desc": "Enzyme replacement (imiglucerase for Gaucher's, factor VIII for hemophilia), therapeutic enzymes (asparaginase for leukemia, alteplase dissolves clots, DNase for CF mucus), and enzyme targets (most drugs inhibit enzymes: statins, ACE inhibitors, kinase inhibitors).\nDesign: replacement needs delivery (mannose targeting to macrophages); inhibitors need selectivity (kinome-wide profiling). Biologics (antibodies) increasingly target enzymes' regulators. Pharmacokinetics (half-life extension via PEGylation) matters as much as potency.", "how": "For replacement: ensure delivery to target cells (glycan targeting); monitor biomarkers. For inhibitors: profile selectivity (panels); watch resistance (kinase mutations). Extend half-life (PEG/Fc fusion) for biologics.", "keys": ["Replacement: Gaucher's, hemophilia.", "Therapeutic: asparaginase, alteplase.", "Most drugs inhibit enzymes.", "Selectivity via profiling.", "Delivery + half-life matter."], "reqs": ["Target enzyme/disease.", "Selectivity data.", "Delivery strategy."], "stds": ["Dosing with units.", "Biomarker endpoints."], "cites": ["Berg JM et al. Biochemistry. 9th ed. Freeman; 2019.", "Druker BJ et al. (Imatinib, NEJM 2001)."], "demo": "#!/usr/bin/env python3\n\"\"\"Enzyme drug classes.\"\"\"\nfor cls, ex in [(\"replacement\", \"imiglucerase\"), (\"therapeutic\", \"asparaginase\"), (\"inhibitor\", \"statins\"), (\"activator\", \"alteplase\")]:\n    print(f\"  {cls:12s}: {ex}\")\n"}, {"tier": "Advanced", "g": "Medicine", "title": "Enzyme Deficiency Diseases", "desc": "Inborn errors (Garrod 1908): phenylketonuria (PAH - phenylalanine accumulates; newborn screening + diet prevents retardation), Tay-Sachs (hexosaminidase A), Gaucher's (glucocerebrosidase - treatable), G6PD deficiency (red-cell oxidative stress - fava beans, antimalarials trigger hemolysis).\nDiagnosis: metabolite accumulation (tandem MS newborn screening); genetics confirms. Treatment: diet (PKU), replacement (Gaucher's), transplant (severe), gene therapy emerging. One gene, one enzyme - Garrod's insight, still true.", "how": "Screen newborns (tandem MS metabolites); confirm genetically. Manage: restrict substrate (PKU diet), replace enzyme, avoid triggers (G6PD). Counsel families (recessive inheritance). Trial gene therapies.", "keys": ["Garrod 1908: inborn errors.", "PKU: screening + diet works.", "Tay-Sachs, Gaucher's: lysosomal.", "G6PD: trigger avoidance.", "Newborn screening saves brains."], "reqs": ["Metabolite data.", "Genetic confirmation.", "Treatment plan."], "stds": ["Metabolite cutoffs.", "Genetics (biallelic)."], "cites": ["Garrod AE. Inborn Errors of Metabolism. 1908.", "Berg JM et al. Biochemistry. 9th ed. Freeman; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"PKU logic.\"\"\"\nprint(\"  PAH deficient -> phenylalanine accumulates -> neurotoxic\")\nprint(\"  newborn screen -> low-Phe diet -> normal development\")\n"}, {"tier": "Advanced", "g": "Biotech", "title": "Enzymes in Molecular Biology (the Toolkit)", "desc": "Molecular biology runs on enzymes: restriction (cut), ligase (paste), polymerases (copy - Taq), reverse transcriptase (RNA→DNA), kinases/phosphatases (label), nucleases (CRISPR-Cas9 cuts, Cas12/13 detect), terminal transferase (tailing), lysozyme/proteinase K (prep).\nEach tool enzyme is characterized (fidelity, processivity, buffer optima) and engineered (high-fidelity pols, fast ligases). The recombinant-DNA revolution was an enzyme revolution - tools first, discoveries follow.", "how": "Choose by need (fidelity: Q5; speed: Taq; blunt: specific ligases); respect buffer optima (salt, temperature); store properly (glycerol, -20 °C). Engineer for applications (hot-start, fusions). Quality-control lots.", "keys": ["Restriction, ligase, polymerase: cut/paste/copy.", "Taq: PCR; RT: RNA→DNA.", "Cas enzymes: cut + detect.", "Characterize: fidelity, optima.", "Tools first, discoveries follow."], "reqs": ["Enzyme choice rationale.", "Buffer conditions.", "QC (activity assay)."], "stds": ["Units defined per enzyme.", "Fidelity (error/base)."], "cites": ["Green MR, Sambrook J. Molecular Cloning. 4th ed. CSHL Press; 2012.", "Berg JM et al. Biochemistry. 9th ed. Freeman; 2019."], "demo": "#!/usr/bin/env python3\n\"\"\"Tool enzyme picker.\"\"\"\ntools = {\"cut DNA\": \"restriction\", \"join DNA\": \"ligase\", \"copy DNA\": \"Taq polymerase\", \"RNA->DNA\": \"reverse transcriptase\"}\nfor need, enz in tools.items():\n    print(f\"  {need:10s}: {enz}\")\n"}, {"tier": "Advanced", "g": "Kinetics", "title": "Pre-Steady-State Kinetics", "desc": "Steady state hides steps - pre-steady-state reveals them: stopped-flow (ms mixing, absorbance/fluorescence), quench-flow (chemical quench, ms timepoints), single-turnover (excess enzyme). Burst kinetics (chymotrypsin: fast acylation burst, slow deacylation) proved covalent intermediates.\nMeasures: individual rate constants (k₂, k₃...), not just kcat/KM. Distinguishes mechanisms steady-state can't (isomerizations, half-site reactivity). The kineticist's microscope - elementary steps resolved.", "how": "Run stopped/quench-flow (ms resolution); fit to mechanisms (KinTek) globally with steady-state data. Use single-turnover to isolate steps; isotope effects to assign rate-determining steps. Demand microscopic reversibility in models.", "keys": ["Steady state hides; pre-steady-state reveals.", "Stopped-flow/quench-flow: ms resolution.", "Burst kinetics proved covalent catalysis.", "Individual rate constants, not just kcat.", "Global fitting (KinTek)."], "reqs": ["ms-resolution data.", "Mechanism model.", "Global fit with steady-state."], "stds": ["Rate constants in s⁻¹.", "Dead times stated."], "cites": ["Fersht A. Structure and Mechanism in Protein Science. Freeman; 1999.", "Johnson KA. Annu Rev Biochem 1992;61:877-902."], "demo": "#!/usr/bin/env python3\n\"\"\"Burst kinetics shape.\"\"\"\nprint(\"  burst phase (fast acylation) -> linear steady state (slow deacylation)\")\nprint(\"  burst amplitude = [active sites]\")\n"}, {"tier": "Advanced", "g": "Structure", "title": "Enzyme Dynamics and Catalysis", "desc": "Enzymes move: femtosecond bond vibrations, microsecond loop closures, millisecond domain motions - and motions couple to chemistry (DHFR's Met20 loop; adenylate kinase's lids). NMR relaxation, single-molecule FRET, and MD simulations watch.\nDebate: are dynamics 'driving' catalysis or just permitting it? Consensus: conformational sampling enables the reactive state; electrostatics do the heavy lifting (Warshel). Design must include dynamics - static structures underdetermine function.", "how": "Probe dynamics (NMR relaxation dispersion, smFRET, H/D exchange); simulate (MD, QM/MM); correlate motions with rates (mutants altering dynamics). Include ensembles in design (not single structures).", "keys": ["Motions span fs to ms.", "DHFR loops couple to catalysis.", "Sampling enables; electrostatics executes.", "NMR/smFRET/MD watch dynamics.", "Design needs ensembles."], "reqs": ["Dynamics data (NMR/MD).", "Rate correlation.", "Timescale assignment."], "stds": ["Timescales stated.", "Order parameters where NMR."], "cites": ["Warshel A. (Nobel 2013, multiscale models).", "Henzler-Wildman KA, Kern D. Nature 2007;450:964-972."], "demo": "#!/usr/bin/env python3\n\"\"\"Motion timescales.\"\"\"\nfor motion, t in [(\"bond vibration\", \"fs\"), (\"loop closure\", \"µs-ms\"), (\"domain motion\", \"ms\"), (\"turnover\", \"ms-s\")]:\n    print(f\"  {motion:15s}: {t}\")\n"}, {"tier": "Advanced", "g": "Systems", "title": "Metabolic Control Analysis", "desc": "Who controls flux? Not the 'rate-limiting step' alone - control is distributed (MCA: flux control coefficients sum to 1). Kacser/Burns and Heinrich/Rapoport (1970s): quantify with elasticities; the summation and connectivity theorems constrain.\nImplication: overexpressing one enzyme rarely boosts flux (control shifts); drug targets need high control coefficients. Systems biology's foundation - from enzymes to networks, quantitatively.", "how": "Measure elasticities (rate vs metabolite); compute control coefficients (perturbation or top-down); verify summation (=1). Target high-control steps for engineering/drugs. Model pathways (COPASI) with measured kinetics.", "keys": ["Control is distributed, not single-step.", "Coefficients sum to 1.", "Elasticities quantify local response.", "Overexpression alone rarely works.", "Target high-control steps."], "reqs": ["Pathway kinetics.", "Perturbation data.", "Steady-state validation."], "stds": ["Coefficients dimensionless.", "Summation verified."], "cites": ["Kacser H, Burns JA. Symp Soc Exp Biol 1973;27:65-104.", "Fell DA. Understanding the Control of Metabolism. Portland; 1997."], "demo": "#!/usr/bin/env python3\n\"\"\"Summation theorem check.\"\"\"\ncoeffs = [0.4, 0.3, 0.2, 0.1]\nprint(f\"  flux control coefficients sum: {sum(coeffs)} (= 1 required)\")\n"}, {"tier": "Advanced", "g": "Origins", "title": "The Origin of Enzymes (Evolution)", "desc": "From ribozymes to proteins: catalytic RNAs → peptides assist → protein enzymes take over (greater chemical diversity, stability). Gene duplication + divergence creates families (TIM barrels everywhere); promiscuity provides starting activities; patchwork recruitment assembles pathways.\nEvidence: ribozymes persist (ribosome), superfamilies share folds not sequences, directed evolution recapitulates divergence in weeks. The protein world won on chemistry - 20 amino acids beat 4 nucleotides for catalysis.", "how": "Reconstruct ancestors (phylogenetics, resurrection); test promiscuous activities as evolutionary starting points. Trace superfamilies (structure, not sequence). Recreate divergence by directed evolution.", "keys": ["Ribozymes → proteins.", "Duplication + divergence.", "Promiscuity seeds new functions.", "TIM barrels: the winning fold.", "Resurrection tests hypotheses."], "reqs": ["Phylogenetic framework.", "Ancestral reconstruction.", "Activity assays."], "stds": ["Trees with support.", "Resurrection methods stated."], "cites": ["Jensen RA. Annu Rev Microbiol 1976;30:409-425.", "Thornton JW. Nat Rev Genet 2004;5:366-375."], "demo": "#!/usr/bin/env python3\n\"\"\"Duplication-divergence.\"\"\"\nprint(\"  gene duplicates -> one keeps old function\")\nprint(\"  other explores (promiscuity) -> new function fixes\")\n"}, {"tier": "Advanced", "g": "Frontiers", "title": "Artificial Metalloenzymes and New-to-Nature Catalysis", "desc": "Beyond biology's reactions: artificial metalloenzymes (biotin-streptavidin anchors for Ir/Rh catalysts - Ward), de novo heme proteins, photocatalytic enzymes, enzymes for non-natural bonds (C-Si, C-B via directed evolution). Chemistry biology never tried.\nStrategy: install synthetic catalysts in protein scaffolds (second coordination sphere tunes selectivity), then evolve. Applications: green synthesis (chiral drugs), new materials, carbon capture (engineered carbonic anhydrases). The boundary between chemo- and bio-catalysis dissolves.", "how": "Anchor synthetic catalysts (biotin-streptavidin, unnatural amino acids); screen for target reactions; evolve selectivity. Characterize (kinetics, structures). Target valuable transformations (chiral synthesis, C-H activation).", "keys": ["Synthetic catalysts in protein scaffolds.", "New-to-nature bonds (C-Si, C-B).", "Second sphere tunes selectivity.", "Evolve after installing.", "Green synthesis applications."], "reqs": ["Catalyst anchor.", "Target reaction.", "Evolution plan."], "stds": ["Turnover numbers.", "Enantioselectivity (ee %)."], "cites": ["Ward TR. Acc Chem Res 2011;44:47-57.", "Arnold FH. (Nobel 2018)."], "demo": "#!/usr/bin/env python3\n\"\"\"Artificial enzyme construction.\"\"\"\nprint(\"  scaffold (streptavidin) + catalyst (Ir complex) -> artificial metalloenzyme\")\nprint(\"  then: directed evolution for selectivity\")\n"}, {"tier": "Advanced", "g": "Frontiers", "title": "Enzyme Futures: AI Design and Cellular Factories", "desc": "AI designs enzymes now: RFdiffusion builds backbones, ProteinMPNN writes sequences - binders and catalysts from prompts (Baker lab, 2020s). Success rates rising; experimental validation still required. The design→test loop accelerates 100×.\nCellular factories: engineered pathways in microbes (artemisinin, opioids in yeast), cell-free systems (transcription-translation + enzymes), minimal cells with designed metabolism. Enzymes become manufacturing - programmable chemistry at scale.", "how": "Design with AI (RFdiffusion/MPNN); validate experimentally (activity, structure); evolve to improve. Build pathways (multigene assembly); optimize flux (MCA); scale (fermentation/cell-free). Mind biosafety (engineered strains contained).", "keys": ["AI designs backbones + sequences.", "Validation still required.", "Pathways in microbes (artemisinin).", "Cell-free manufacturing.", "Programmable chemistry at scale."], "reqs": ["AI design method.", "Experimental validation.", "Pathway/flux data."], "stds": ["Design success rates.", "Titres (g/L)."], "cites": ["Watson JL et al. Nature 2023;620:1089-1100 (RFdiffusion).", "Paddon CJ et al. Nature 2013;496:528-532."], "demo": "#!/usr/bin/env python3\n\"\"\"AI enzyme design pipeline.\"\"\"\nfor i, s in enumerate([\"prompt (reaction)\", \"RFdiffusion (backbone)\", \"ProteinMPNN (sequence)\", \"test in lab\", \"evolve\"], 1):\n    print(f\"  {i}. {s}\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-ENZYMS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    signature_label:sig?'Signature-generated original treatment - clearly labeled Signature-made and never presented as authentic public record.':'Public-harvest record - real, fact-checked domain knowledge.',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||true;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-ENZYMS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-enzymes-signature-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('enzymes-signature',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
